step-aggregate.interface:
interface Step<TParams = {}, TConfig = {}> {
  // Identidad
  id: string;                              // 'products.create'
  moduleId: ModuleId;                      // 'products'
  path: PathPattern;                       // '/productos/nuevo' | '/productos/:id'

  // RenderStrategy
  render: {
    shell: ShellId | 'inherit';            // 'sidebar-topbar' | 'fullscreen' | etc.
    mode?: 'server' | 'client' | 'edge';   // Next.js render mode (default: 'client')
    slots: SlotTree;                       // ⭐ NOMBRADO, no array
  };

  // Metadatos
  title: string | TitleFn<TParams>;
  breadcrumbs?: BreadcrumbItem[] | BreadcrumbsFn<TParams>;
  permissions?: Permission[];

  // Lifecycle
  guards: Guard[];                         // preconditions (Auth, Role, FeatureFlag)
  transitions: {
    next?:    TransitionDecision;          // push | replace | redirect | complete | fail
    cancel?:  TransitionDecision;
    back?:    TransitionDecision;
    [custom: string]: TransitionDecision;  // ej: onCompleted, onError
  };

  // Contratos (D10 — L0/L1/L2 declarados)
  contracts: {
    config: ConfigContract<TConfig>;       // L0 — props configurables por la app
    slots: SlotContract;                   // L1 — slots inyectables externos
    events: EventContract;                 // L2 — eventos del step
  };
}

type SlotTree = {
  // Layout slots (override del shell)
  'header'?:        SlotContent;
  'header.left'?:   SlotContent;
  'header.center'?: SlotContent;
  'header.right'?:  SlotContent;
  'sidebar'?:       SlotContent | 'hidden';
  'sidebar.nav'?:   SlotContent;
  'footer'?:        SlotContent;
  'right-panel'?:   SlotContent;

  // Content slots
  'main':           SlotContent;            // OBLIGATORIO (la view principal)
  'main.actions'?:  SlotContent;
  'main.filters'?:  SlotContent;
  'main.tabs'?:     SlotContent;
  'main.empty'?:    SlotContent;

  // Custom slots del módulo
  [custom: `slot.${string}`]?: SlotContent;
};

type SlotContent =
  | LazyComponent                                                         // dinámico, code-split
  | { component: LazyComponent; props?: object; when?: Predicate };       // con props o condicional

type TransitionDecision =
  | { type: 'push';     stepId: string;  params?: object }                // apila
  | { type: 'replace';  stepId: string;  params?: object }                // reemplaza (no historia)
  | { type: 'redirect'; url: string }                                      // navega fuera
  | { type: 'complete'; output?: unknown }                                 // termina flow
  | { type: 'fail';     error: StepError };                                // falla con error

contexts.composer:
// packages/shell-runtime/src/SurteProvider.tsx
export function SurteProvider({ config, children }) {
  const session = useSessionInit(config);
  const registry = useModuleRegistry(config.modules);
  const eventBus = useMemo(() => createEventBus(), []);
  const stepState = useStepState();

  return composeProviders(
    [
      [AppContext.Provider,     { value: config }],
      [SessionContext.Provider, { value: session }],
      [ModuleContext.Provider,  { value: registry }],
      [EventContext.Provider,   { value: eventBus }],
      [StepContext.Provider,    { value: stepState }],
    ],
    children
  );
}

