// packages/core/src/container.ts
export const TOKENS = {
  Clock:                  Symbol('Clock'),
  Logger:                 Symbol('Logger'),
  EventBus:               Symbol('EventBus'),
  ProductRepository:      Symbol('ProductRepository'),
  SupplierRepository:     Symbol('SupplierRepository'),
  StockRepository:        Symbol('StockRepository'),
  ExpiryRepository:       Symbol('ExpiryRepository'),
  PurchaseRepository:     Symbol('PurchaseRepository'),
  SaleRepository:         Symbol('SaleRepository'),
  AuthService:            Symbol('AuthService'),
} as const;

// Cada módulo bindea SUS tokens en su lifecycle.onBootstrap
// La app NO conoce qué implementación usa cada módulo.
